message = 'Zsmxsm sc sx Zyvilsec Zvkjk.'
for shift in range(1, 26):
    result = ''
    for char in message:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            result += chr((ord(char) - base - shift) % 26 + base)
        else:
            result += char
    print(f'Shift {shift:2d}: {result}')
"

